sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
   // Create a new GlideAjax instance for calling the server script
    var getReasonDesc = new GlideAjax('x_hsb11_mss_c_proc.HSBCTradeTaskUtils');

    // Set the server script name
    getReasonDesc.addParam('sysparm_name', 'getReasonDescription');

    // Pass the new value (reason code) as a parameter to the server script
    getReasonDesc.addParam('sysparm_reason_code', newValue);

    // Make an asynchronous server call to get the reason description
    getReasonDesc.getXML(function(response) {
        // Extract the 'answer' attribute from the server's response
        var answer = response.responseXML.documentElement.getAttribute('answer');
        // Set the 'reason_description' field on the form with the retrieved answer
        g_form.setValue('reason_description', answer);
    });
}
